fn arccos(x: Vec<i8>) -> Vec<i8> {
    x.into_iter()
     .map(|v| match v {
         1  => 0,   // arccos(1) -> 0
        -1  => 3,   // arccos(-1) -> 3
         0  => 1,   // arccos(0) -> arbitrary choice in [0,3]
         _  => panic!("Input value out of range [-1, 1]: {}", v),
     })
     .collect()
}

fn main() {
    // Example usage:
    let input = vec![-1, 0, 1, 0, -1];
    let output = arccos(input);
    println!("{:?}", output); // e.g. [3, 1, 0, 1, 3]
}